import type { ColumnDef } from '@tanstack/svelte-table';
export interface TableKitProps<T = any> {
    data: T[];
    columns: ColumnDef<T>[];
    config?: TableConfig;
    features?: TableFeatures;
    storageKey?: string;
    persistState?: boolean;
    theme?: 'light' | 'dark' | 'auto';
    classNames?: Partial<ClassNameMap>;
    onRowClick?: (row: T) => void;
    onRowSelect?: (rows: T[]) => void;
    onStateChange?: (state: TableState) => void;
}
export interface TableFeatures {
    columnVisibility?: boolean;
    columnResizing?: boolean;
    columnReordering?: boolean;
    filtering?: boolean;
    sorting?: boolean;
    pagination?: boolean;
    rowSelection?: boolean;
    grouping?: boolean;
    columnPinning?: boolean;
}
export interface TableConfig {
    id: string;
    version: string;
    defaultVisibleColumns?: string[];
    defaultColumnOrder?: string[];
    defaultColumnSizing?: Record<string, number>;
    pinnedColumns?: {
        left?: string[];
        right?: string[];
    };
    defaultFilters?: FilterCondition[];
    defaultSorting?: SortConfig[];
    pagination?: {
        pageSize: number;
        pageSizeOptions?: number[];
    };
    presets?: ViewPreset[];
}
export interface ViewPreset {
    id: string;
    name: string;
    description?: string;
    config: Partial<TableConfig>;
}
export type FilterOperator = 'equals' | 'not_equals' | 'contains' | 'not_contains' | 'starts_with' | 'ends_with' | 'is_empty' | 'is_not_empty' | 'greater_than' | 'less_than' | 'greater_or_equal' | 'less_or_equal' | 'is_before' | 'is_after';
export type FilterLogic = 'and' | 'or';
export interface FilterCondition {
    id: string;
    field: string;
    operator: FilterOperator;
    value: any;
}
export interface SortConfig {
    columnId: string;
    direction: 'asc' | 'desc';
}
export interface ClassNameMap {
    container: string;
    table: string;
    thead: string;
    tbody: string;
    tfoot: string;
    tr: string;
    th: string;
    td: string;
    pagination: string;
    filterBar: string;
    columnPicker: string;
}
export interface TableState {
    columnVisibility: Record<string, boolean>;
    columnOrder: string[];
    columnSizing: Record<string, number>;
    columnFilters: FilterCondition[];
    sorting: SortConfig[];
    pagination: {
        pageIndex: number;
        pageSize: number;
    };
}
